create extension if not exists pgcrypto;
create type question_status as enum ('draft','published','retired');create type question_difficulty as enum ('normal','hard');create type translation_status as enum ('draft','reviewed');create type choice_value as enum ('A','B');create type challenge_status as enum ('draft','published','archived');
create table questions(id uuid primary key default gen_random_uuid(),canonical_key text unique not null check(canonical_key~'^[a-z0-9]+(?:-[a-z0-9]+)*$'),status question_status not null default 'draft',content_rating text not null default 'clean' check(content_rating='clean'),difficulty question_difficulty not null,daily_eligible boolean not null default false,quality_score integer not null default 0 check(quality_score between 0 and 100),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),last_reviewed_at timestamptz);
create table question_localizations(id uuid primary key default gen_random_uuid(),question_id uuid not null references questions on delete cascade,locale text not null check(locale in('en','zh-Hant')),option_a text not null check(length(option_a) between 1 and 160),option_b text not null check(length(option_b) between 1 and 160),translation_status translation_status not null default 'draft',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(question_id,locale));
create table categories(id uuid primary key default gen_random_uuid(),slug text unique not null,name_en text not null,name_zh_hant text not null);insert into categories(slug,name_en,name_zh_hant) values('general','General','綜合'),('funny','Funny','搞笑'),('hard','Hard','超難'),('couples','Couples','情侶');
create table question_categories(question_id uuid references questions on delete cascade,category_id uuid references categories on delete cascade,primary key(question_id,category_id));
create table question_votes(id uuid primary key default gen_random_uuid(),question_id uuid not null references questions on delete cascade,anonymous_user_hash text not null,choice choice_value not null,locale text not null check(locale in('en','zh-Hant')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(question_id,anonymous_user_hash));
create table question_vote_totals(question_id uuid primary key references questions on delete cascade,option_a_count bigint not null default 0 check(option_a_count>=0),option_b_count bigint not null default 0 check(option_b_count>=0),updated_at timestamptz not null default now());
create table daily_challenges(id uuid primary key default gen_random_uuid(),challenge_date date unique not null,status challenge_status not null default 'draft',created_at timestamptz not null default now());
create table daily_challenge_questions(daily_challenge_id uuid references daily_challenges on delete cascade,question_id uuid references questions on delete restrict,position smallint not null check(position between 1 and 10),unique(daily_challenge_id,question_id),unique(daily_challenge_id,position));
create table daily_predictions(id uuid primary key default gen_random_uuid(),challenge_date date not null,question_id uuid not null references questions,anonymous_user_hash text not null,personal_choice choice_value not null,predicted_choice choice_value not null,benchmark_choice choice_value,benchmark_a_count bigint not null,benchmark_b_count bigint not null,is_correct boolean,scoreable boolean not null,created_at timestamptz not null default now(),unique(challenge_date,question_id,anonymous_user_hash));
create index questions_status_idx on questions(status);create index questions_daily_idx on questions(daily_eligible) where status='published';create index question_categories_category_idx on question_categories(category_id,question_id);create index question_localizations_lookup_idx on question_localizations(locale,question_id);create index daily_challenges_date_idx on daily_challenges(challenge_date);create index question_votes_anon_idx on question_votes(anonymous_user_hash);create index daily_predictions_lookup_idx on daily_predictions(challenge_date,anonymous_user_hash);
alter table questions enable row level security;alter table question_localizations enable row level security;alter table categories enable row level security;alter table question_categories enable row level security;alter table question_votes enable row level security;alter table question_vote_totals enable row level security;alter table daily_challenges enable row level security;alter table daily_challenge_questions enable row level security;alter table daily_predictions enable row level security;
create policy "published questions readable" on questions for select using(status='published');create policy "reviewed localizations readable" on question_localizations for select using(translation_status='reviewed');create policy "categories readable" on categories for select using(true);create policy "question categories readable" on question_categories for select using(true);create policy "published challenges readable" on daily_challenges for select using(status='published');create policy "published challenge questions readable" on daily_challenge_questions for select using(exists(select 1 from daily_challenges d where d.id=daily_challenge_id and d.status='published'));
create or replace function cast_question_vote(p_question_id uuid,p_anonymous_user_hash text,p_choice choice_value,p_locale text) returns table(option_a_count bigint,option_b_count bigint) language plpgsql security definer set search_path=public as $$declare old choice_value;begin if not exists(select 1 from questions where id=p_question_id and status='published') or p_locale not in('en','zh-Hant') then raise exception 'invalid vote';end if;perform pg_advisory_xact_lock(hashtextextended(p_question_id::text,0));insert into question_vote_totals(question_id) values(p_question_id) on conflict do nothing;select choice into old from question_votes where question_id=p_question_id and anonymous_user_hash=p_anonymous_user_hash for update;if old is null then insert into question_votes(question_id,anonymous_user_hash,choice,locale) values(p_question_id,p_anonymous_user_hash,p_choice,p_locale);elsif old<>p_choice then update question_votes set choice=p_choice,locale=p_locale,updated_at=now() where question_id=p_question_id and anonymous_user_hash=p_anonymous_user_hash;end if;if old is null then update question_vote_totals set option_a_count=option_a_count+(p_choice='A')::int,option_b_count=option_b_count+(p_choice='B')::int,updated_at=now() where question_id=p_question_id;elsif old<>p_choice then update question_vote_totals set option_a_count=greatest(0,option_a_count-(old='A')::int)+(p_choice='A')::int,option_b_count=greatest(0,option_b_count-(old='B')::int)+(p_choice='B')::int,updated_at=now() where question_id=p_question_id;end if;return query select t.option_a_count,t.option_b_count from question_vote_totals t where t.question_id=p_question_id;end$$;
revoke all on function cast_question_vote(uuid,text,choice_value,text) from public,anon,authenticated;
create or replace function submit_daily_prediction(p_challenge_date date,p_question_id uuid,p_anonymous_user_hash text,p_personal_choice choice_value,p_prediction choice_value,p_locale text) returns table(scoreable boolean,is_correct boolean,benchmark_choice choice_value,option_a_count bigint,option_b_count bigint,repeated boolean) language plpgsql security definer set search_path=public as $$declare existing daily_predictions%rowtype;declare a bigint;declare b bigint;declare bench choice_value;declare can_score boolean;begin perform pg_advisory_xact_lock(hashtextextended(p_question_id::text,0));select * into existing from daily_predictions where challenge_date=p_challenge_date and question_id=p_question_id and anonymous_user_hash=p_anonymous_user_hash;if found then select t.option_a_count,t.option_b_count into a,b from question_vote_totals t where t.question_id=p_question_id;return query select existing.scoreable,existing.is_correct,existing.benchmark_choice,coalesce(a,0),coalesce(b,0),true;return;end if;if not exists(select 1 from daily_challenge_questions dcq join daily_challenges dc on dc.id=dcq.daily_challenge_id where dc.challenge_date=p_challenge_date and dc.status='published' and dcq.question_id=p_question_id) then raise exception 'question is not in challenge';end if;select t.option_a_count,t.option_b_count into a,b from question_vote_totals t where t.question_id=p_question_id; a:=coalesce(a,0);b:=coalesce(b,0);can_score:=a+b>0 and a<>b;bench:=case when not can_score then null when a>b then 'A'::choice_value else 'B'::choice_value end;insert into daily_predictions(challenge_date,question_id,anonymous_user_hash,personal_choice,predicted_choice,benchmark_choice,benchmark_a_count,benchmark_b_count,is_correct,scoreable)values(p_challenge_date,p_question_id,p_anonymous_user_hash,p_personal_choice,p_prediction,bench,a,b,case when can_score then p_prediction=bench else null end,can_score);perform cast_question_vote(p_question_id,p_anonymous_user_hash,p_personal_choice,p_locale);select t.option_a_count,t.option_b_count into a,b from question_vote_totals t where t.question_id=p_question_id;return query select can_score,case when can_score then p_prediction=bench else null end,bench,a,b,false;end$$;
revoke all on function submit_daily_prediction(date,uuid,text,choice_value,choice_value,text) from public,anon,authenticated;
